#!/usr/bin/env python3
"""Generate the gateway route ownership table from the mounted gateway app.

The table is written to docs/reference/gateway-route-ownership.md. Run it with
`uv run python scripts/generate_gateway_route_ownership.py`. Pass `--check` to exit with
status 1 when the committed page differs from the code.
"""

import argparse
import os
import sys
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[1]
PAGE_PATH = REPO_ROOT / "docs" / "reference" / "gateway-route-ownership.md"

PREAMBLE = """# Reference: Gateway Route Ownership

<!-- Generated by scripts/generate_gateway_route_ownership.py. Do not edit by hand. -->

This table lists every public route that the gateway mounts. It names the service that owns
each route, and the mode in which the gateway serves it.

## Modes

- `proxy`: the gateway forwards the request to the owner. The owner checks the caller's token and
  every object permission (ADR-0001, ADR-0015). The gateway adds no permission check, except on the
  routes that the call-owning-services how-to guide lists (TASK-0845). A composite route, which
  combines several owner reads, is a `proxy` row that checks the permission at the gateway.
- `relay`: the gateway opens a WebSocket to the owner and relays its frames.
- `local`: the gateway answers the request itself. It holds no domain state.

## Owner rules

- The gateway handles authentication, routing, WebSocket fan-out, and OpenAPI aggregation. It
  owns no domain state.
- The gateway does not mount owner alias paths. A browser reaches only the paths in this table.
- A route with two owners calls both owners. The gateway returns the owner replies. It never
  fills a missing value with a default.

## Routes

"""


def render() -> str:
    """Return the page text for the routes that the gateway app mounts."""
    # The app builds its settings at import time and needs the key. The route table does not
    # depend on it, and the generator never contacts SpiceDB. The value is a placeholder.
    os.environ.setdefault("RUNEFOBLE_SPICEDB_PRESHARED_KEY", "generator-placeholder")
    from gateway_api.main import app
    from gateway_api.route_ownership import owned_routes

    lines = [
        "| Method | Gateway path | Owner | Mode | Source |",
        "|---|---|---|---|---|",
    ]
    for row in owned_routes(app):
        lines.append(f"| {row.method} | `{row.path}` | {row.owner} | {row.mode} | `{row.source}` |")
    return PREAMBLE + "\n".join(lines) + "\n"


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail when the page is stale")
    args = parser.parse_args()
    text = render()
    if args.check:
        current = PAGE_PATH.read_text(encoding="utf-8") if PAGE_PATH.exists() else ""
        if current != text:
            print(f"{PAGE_PATH} is stale. Run scripts/generate_gateway_route_ownership.py.")
            return 1
        return 0
    PAGE_PATH.write_text(text, encoding="utf-8")
    print(f"wrote {PAGE_PATH}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
